package com.ptms.service; import com.ptms.*; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class EmployeeService{private final EmployeeRepository r;public EmployeeService(EmployeeRepository r){this.r=r;}public List<EmployeeDto>all(){return r.findAll().stream().map(this::dto).toList();}public EmployeeDto save(EmployeeDto d){Employee e=d.id()==null?new Employee():r.findById(d.id()).orElseThrow();e.setEmployeeCode(d.employeeCode());e.setName(d.name());e.setVehicleNumber(d.vehicleNumber());e.setTeam(d.team());e.setDepartment(d.department());e.setParkingPass(d.parkingPass());e.setDefaultEntryTime(d.defaultEntryTime());return dto(r.save(e));}public void delete(Long id){r.deleteById(id);}private EmployeeDto dto(Employee e){return new EmployeeDto(e.getId(),e.getEmployeeCode(),e.getName(),e.getVehicleNumber(),e.getTeam(),e.getDepartment(),e.isParkingPass(),e.getDefaultEntryTime());}}
